const {
    IOSConfig,
    withAppDelegate,
    withDangerousMod,
    withInfoPlist,
    withXcodeProject,
} = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

// The iOS 27 SDK asserts at launch unless the app adopts the scene life cycle. Expo adopts it in
// SDK 57 (ExpoAppSceneDelegate, generated by the SDK 58 template); this backports that to SDK 54:
// the window moves from AppDelegate to a generated SceneDelegate, the scene manifest goes into
// Info.plist, and scene events are fed back to ExpoAppDelegate (plugins/ios-scene/*.swift).
// expo-dev-launcher's start is deferred to the scene's window in patches/expo-dev-launcher+6.0.20.patch.
// Remove this plugin, plugins/ios-scene and that part of the patch on SDK 57+.

const SOURCE_DIR = path.join(__dirname, 'ios-scene');
const SWIFT_FILES = [
    'ExpoReactNativeFactoryProvider.swift',
    'SceneEventForwarder.swift',
    'ExpoAppSceneDelegate.swift',
    'SceneDelegate.swift',
];

function withSceneSources(config) {
    config = withDangerousMod(config, ['ios', (config) => {
        const projectName = config.modRequest.projectName;
        const targetDir = path.join(config.modRequest.platformProjectRoot, projectName);
        for (const file of SWIFT_FILES) {
            fs.copyFileSync(path.join(SOURCE_DIR, file), path.join(targetDir, file));
        }
        return config;
    }]);

    return withXcodeProject(config, (config) => {
        const project = config.modResults;
        const projectName = config.modRequest.projectName;
        const { uuid: targetUuid } = IOSConfig.XcodeUtils.getApplicationNativeTarget({ project, projectName });
        for (const file of SWIFT_FILES) {
            const filepath = `${projectName}/${file}`;
            if (project.hasFile(filepath)) {
                continue;
            }
            IOSConfig.XcodeUtils.addBuildSourceFileToGroup({
                filepath,
                groupName: projectName,
                project,
                targetUuid,
            });
        }
        return config;
    });
}

function withSceneManifest(config) {
    return withInfoPlist(config, (config) => {
        config.modResults.UIApplicationSceneManifest = {
            UIApplicationSupportsMultipleScenes: false,
            UISceneConfigurations: {
                UIWindowSceneSessionRoleApplication: [
                    {
                        UISceneConfigurationName: 'Default Configuration',
                        UISceneDelegateClassName: '$(PRODUCT_MODULE_NAME).SceneDelegate',
                    },
                ],
            },
        };
        return config;
    });
}

// The SDK 54 template creates the window and starts React Native in didFinishLaunching; under the
// scene life cycle SceneDelegate does both, reaching the factory through ExpoReactNativeFactoryProvider.
// bindReactNativeFactory stays: expo-dev-launcher recreates the root view through it.
const CLASS_DECLARATION = /(class AppDelegate: ExpoAppDelegate)( \{)/;
const WINDOW_START = /\n#if os\(iOS\) \|\| os\(tvOS\)\n\s*window = UIWindow\(frame: UIScreen\.main\.bounds\)\n\s*factory\.startReactNative\([\s\S]*?\)\n#endif\n/;

function withSceneAppDelegate(config) {
    return withAppDelegate(config, (config) => {
        if (config.modResults.language !== 'swift') {
            throw new Error('withIosSceneLifecycle: expected a Swift AppDelegate');
        }
        let contents = config.modResults.contents;
        if (!contents.includes('ExpoReactNativeFactoryProvider')) {
            if (!CLASS_DECLARATION.test(contents)) {
                throw new Error('withIosSceneLifecycle: could not find `class AppDelegate: ExpoAppDelegate {` in AppDelegate.swift');
            }
            contents = contents.replace(CLASS_DECLARATION, '$1, ExpoReactNativeFactoryProvider$2');
        }
        if (WINDOW_START.test(contents)) {
            contents = contents.replace(
                WINDOW_START,
                '\n    // SceneDelegate creates the window and starts React Native (scene life cycle, iOS 27 SDK).\n',
            );
        } else if (contents.includes('factory.startReactNative(')) {
            throw new Error('withIosSceneLifecycle: could not remove the window setup from AppDelegate.swift');
        }
        config.modResults.contents = contents;
        return config;
    });
}

module.exports = function withIosSceneLifecycle(config) {
    config = withSceneSources(config);
    config = withSceneManifest(config);
    config = withSceneAppDelegate(config);
    return config;
};
